voidpf IOSystem2Unzip::open(voidpf opaque, const char *filename, int mode) {
    IOSystem *io_system = reinterpret_cast<IOSystem *>(opaque);

    const char *mode_fopen = nullptr;
    if ((mode & ZLIB_FILEFUNC_MODE_READWRITEFILTER) == ZLIB_FILEFUNC_MODE_READ) {
        mode_fopen = "rb";
    } else {
        if (mode & ZLIB_FILEFUNC_MODE_EXISTING) {
            mode_fopen = "r+b";
        } else {
            if (mode & ZLIB_FILEFUNC_MODE_CREATE) {
                mode_fopen = "wb";
            }
        }
    }

    return (voidpf)io_system->Open(filename, mode_fopen);
}

voidpf IOSystem2Unzip::opendisk(voidpf opaque, voidpf stream, uint32_t number_disk, int mode) {
    ZipFile *io_stream = (ZipFile *)stream;
    voidpf ret = NULL;
    size_t i;

    char *disk_filename = (char*)malloc(io_stream->m_Filename.length() + 1);
    strncpy(disk_filename, io_stream->m_Filename.c_str(), io_stream->m_Filename.length() + 1);
    for (i = io_stream->m_Filename.length() - 1; i >= 0; i -= 1)
    {
        if (disk_filename[i] != '.')
            continue;
        snprintf(&disk_filename[i], io_stream->m_Filename.length() - i, ".z%02u", number_disk + 1);
        break;
    }

    if (i >= 0)
        ret = open(opaque, disk_filename, mode);

    free(disk_filename);
    return ret;
}

uLong IOSystem2Unzip::read(voidpf /*opaque*/, voidpf stream, void *buf, uLong size) {
    IOStream *io_stream = (IOStream *)stream;

    return static_cast<uLong>(io_stream->Read(buf, 1, size));
}

uLong IOSystem2Unzip::write(voidpf /*opaque*/, voidpf stream, const void *buf, uLong size) {
    IOStream *io_stream = (IOStream *)stream;

    return static_cast<uLong>(io_stream->Write(buf, 1, size));
}

long IOSystem2Unzip::tell(voidpf /*opaque*/, voidpf stream) {
    IOStream *io_stream = (IOStream *)stream;

    return static_cast<long>(io_stream->Tell());
}

reasoning:
I found the bug. In `IOSystem2Unzip::opendisk`:

```cpp
voidpf IOSystem2Unzip::opendisk(voidpf opaque, voidpf stream, uint32_t number_disk, int mode) {
    ZipFile *io_stream = (ZipFile *)stream;
    voidpf ret = NULL;
    size_t i;

    char *disk_filename = (char*)malloc(io_stream->m_Filename.length() + 1);
    strncpy(disk_filename, io_stream->m_Filename.c_str(), io_stream->m_Filename.length() + 1);
    for (i = io_stream->m_Filename.length() - 1; i >= 0; i -= 1)
    {
        if (disk_filename[i] != '.')
            continue;
        snprintf(&disk_filename[i], io_stream->m_Filename.length() - i, ".z%02u", number_disk + 1);
        break;
    }

    if (i >= 0)
        ret = open(opaque, disk_filename, mode);

    free(disk_filename);
    return ret;
}
```

`i` is `size_t` (unsigned), so `i >= 0` is always true. If the filename doesn't contain a dot, the loop continues: `i` decrements from `length - 1` down to 0, then `i -= 1` wraps it around to `SIZE_MAX`, and the loop continues, accessing `disk_filename[SIZE_MAX]` — way out of bounds read. Eventually it might find a '.' somewhere in memory and then do a `snprintf` there... causing an out-of-bounds write or crash.

More precisely:
- If `m_Filename` has no dot, the loop never hits the `break`. When `i` reaches 0: `disk_filename[0] != '.'` → continue → `i -= 1` → `i = SIZE_MAX` → `i >= 0` still true → `disk_filename[SIZE_MAX]` access. That access is `*(disk_filename - 1)` effectively (SIZE_MAX as index wraps pointer arithmetic to disk_filename - 1). It keeps reading backwards through memory until it either segfaults or hits a byte equal to '.'.

So to trigger the bug, we need assimp to open a ZIP archive whose filename has no dot, and the ZIP must be a multi-disk (spanned) archive so that `opendisk` gets invoked.

